              email: 'visual-qa-edit@example.com',
              name: '비주얼 QA 사용자',
              handle: 'visual-qa-user',
              favoriteTeam: 'LG',
              favoriteTeamColor: '#2b8a6e',
              role: 'ROLE_USER',
              profileImageUrl: null,
              provider: 'LOCAL',
              bio: 'Visual QA deterministic cheer edit fixture',
